# serveur_test.py — uvicorn serveur_test:app --port 8100
import asyncio
import random

from fastapi import FastAPI, HTTPException

app = FastAPI()
COURS = {"IWDA": 92.5, "EMIM": 26.9, "CSPX": 512.3, "AGGH": 5.3, "VWRL": 108.4}
etat = {"flaky_appels": 0}


@app.get("/cours/{ticker}")
async def cours(ticker: str):
    if ticker == "SLOW":
        await asyncio.sleep(3)
        return {"ticker": ticker, "cours": 1.0}
    if ticker == "FLAKY":
        etat["flaky_appels"] += 1
        if etat["flaky_appels"] % 2 == 1:
            raise HTTPException(status_code=500, detail="panne simulée")
        return {"ticker": ticker, "cours": 42.0}
    await asyncio.sleep(0.2)
    if ticker not in COURS:
        raise HTTPException(status_code=404, detail="ticker inconnu")
    return {"ticker": ticker, "cours": COURS[ticker]}
