# client.py
import asyncio

import httpx

BASE = "http://127.0.0.1:8100"
TICKERS = ["IWDA", "EMIM", "CSPX", "AGGH", "VWRL", "SLOW", "FLAKY", "NOPE"]


async def fetch_un(client: httpx.AsyncClient, ticker: str) -> float:
    reponse = await client.get(f"{BASE}/cours/{ticker}", timeout=1.0)
    reponse.raise_for_status()
    return reponse.json()["cours"]


def classer(res) -> dict:
    """Fonction pure : transforme résultat-ou-exception en entrée de rapport."""
    if isinstance(res, httpx.TimeoutException):
        return {"statut": "timeout"}
    if isinstance(res, httpx.HTTPStatusError):
        return {"statut": f"http_{res.response.status_code}"}
    if isinstance(res, Exception):
        return {"statut": "erreur", "detail": str(res)}
    return {"statut": "ok", "cours": res}


async def main() -> None:
    async with httpx.AsyncClient() as client:
        async with asyncio.timeout(5):            # garde-fou GLOBAL
            resultats = await asyncio.gather(
                *(fetch_un(client, t) for t in TICKERS),
                return_exceptions=True,
            )
    rapport = {t: classer(r) for t, r in zip(TICKERS, resultats)}
    for ticker, info in rapport.items():
        print(f"{ticker:<6} {info}")


asyncio.run(main())
```

Rapport obtenu :

```
IWDA   {'statut': 'ok', 'cours': 92.5}
...
SLOW   {'statut': 'timeout'}
FLAKY  {'statut': 'http_500'}
NOPE   {'statut': 'http_404'}
```

Pourquoi le timeout global de 5 s ne se déclenche pas : SLOW est tué à 1 s par SON timeout de requête — le lot entier finit en ~1 s. Les deux niveaux ont des rôles distincts : le timeout par requête borne chaque élément, le global protège contre l'accumulation (20 requêtes à 0.9 s chacune passeraient le premier mais pas une dérive générale).

Et le réflexe chapitre 7 : `classer()` est pure — elle se teste avec des exceptions construites à la main, sans serveur ni réseau.
